from pathlib import Path
import re

p=Path('app/src/main/assets/prototype/index_v3.html')
s=p.read_text(encoding='utf-8')

# Add a robust login overlay and actual biometric button only once.
if 'id="authOverlay"' not in s:
    insert='''<div id="authOverlay" style="display:flex;position:fixed;inset:0;z-index:99999;background:#071b3a;align-items:center;justify-content:center;padding:18px"><div style="width:min(440px,100%);background:#0b1f45;border:1px solid #ffffff33;border-radius:24px;padding:24px;color:#fff"><img src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 108 108'%3E%3Crect width='108' height='108' rx='24' fill='%23071b3a'/%3E%3Cpath d='M10 18V11Q10 8 13 8H95Q98 8 98 11V18' fill='none' stroke='%231199f4' stroke-width='5'/%3E%3Cpath d='M12 20Q12 13 19 13H89Q96 13 96 20V66Q96 89 54 101Q12 89 12 66Z' fill='%230b1f45' stroke='%231198f4' stroke-width='4'/%3E%3Ctext x='54' y='52' fill='white' font-size='24' font-family='Arial' font-weight='900' text-anchor='middle'%3ERGA%3C/text%3E%3Cpath d='M22 61H86' stroke='%23119cf4' stroke-width='3'/%3E%3Ctext x='54' y='80' fill='%23119cf4' font-size='17' font-family='Arial' font-weight='900' text-anchor='middle'%3EPRO%3C/text%3E%3C/svg%3E" style="width:120px;height:120px;display:block;margin:0 auto 12px;border-radius:24px"><h1 style="text-align:center;margin:0 0 6px">RgaPro</h1><p style="text-align:center;color:#bfd0e8">Acceso seguro</p><input id="authUser" placeholder="Usuario" style="width:100%;padding:13px;border-radius:12px;border:1px solid #ffffff33;background:#061633;color:#fff;margin:6px 0"><input id="authPin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN de 6 dígitos" style="width:100%;padding:13px;border-radius:12px;border:1px solid #ffffff33;background:#061633;color:#fff;margin:6px 0"><button onclick="rgLogin()" style="width:100%;padding:13px;border:0;border-radius:12px;background:#0d55c7;color:#fff;font-weight:900;margin-top:6px">Entrar</button><button id="rgBio" onclick="rgBioLogin()" style="display:none;width:100%;padding:13px;border:0;border-radius:12px;background:#e9f1ff;color:#0d55c7;font-weight:900;margin-top:8px">🔐 Acceso biométrico</button><button onclick="rgNewUser()" style="width:100%;padding:13px;border:1px solid #168cff;border-radius:12px;background:transparent;color:#66b8ff;font-weight:900;margin-top:8px">＋ Nuevo usuario</button><button onclick="rgResetSecurity()" style="width:100%;padding:13px;border:1px solid #ff9f9f;border-radius:12px;background:transparent;color:#ffd2d2;font-weight:900;margin-top:8px">♻️ Reiniciar seguridad</button><div id="rgAuthMsg" style="margin-top:8px;text-align:center;color:#ffcf99;font-size:12px"></div></div></div><script>\nfunction rgUsers(){try{return JSON.parse(localStorage.getItem('rgapro_users')||'[]')}catch(e){return[]}}\nfunction rgLogin(){const u=(document.getElementById('authUser').value||'').trim(),p=(document.getElementById('authPin').value||'').trim();const a=rgUsers();if(!a.length){document.getElementById('rgAuthMsg').textContent='No hay usuarios. Pulsa Nuevo usuario.';return}const ok=a.find(x=>x.user===u&&x.pin===p);if(!ok){document.getElementById('rgAuthMsg').textContent='Usuario o PIN incorrectos.';return}localStorage.setItem('rgapro_session',u);document.getElementById('authOverlay').style.display='none';}\nfunction rgNewUser(){const u=prompt('Nuevo usuario');if(!u)return;const p=prompt('PIN de 6 dígitos');if(!/^[0-9]{6}$/.test(p||'')){alert('El PIN debe tener 6 dígitos.');return}const a=rgUsers();if(a.some(x=>x.user===u)){alert('Ese usuario ya existe.');return}a.push({user:u,pin:p});localStorage.setItem('rgapro_users',JSON.stringify(a));document.getElementById('authUser').value=u;document.getElementById('authPin').value=p;document.getElementById('rgAuthMsg').textContent='Usuario creado. Ya puedes entrar.'}\nfunction rgResetSecurity(){localStorage.removeItem('rgapro_users');localStorage.removeItem('rgapro_session');try{RgaProCamera.resetSecurity()}catch(e){}document.getElementById('authUser').value='';document.getElementById('authPin').value='';document.getElementById('rgAuthMsg').textContent='Seguridad reiniciada. Crea un usuario nuevo.'}\nfunction rgBioLogin(){try{RgaProCamera.biometricUnlock()}catch(e){document.getElementById('rgAuthMsg').textContent='Biometría no disponible. Usa el PIN.'}}\nwindow.onBiometricSuccess=function(){let u=document.getElementById('authUser').value.trim()||localStorage.getItem('rgapro_session')||'';if(!u){const a=rgUsers();if(a.length===1)u=a[0].user}if(u){localStorage.setItem('rgapro_session',u);document.getElementById('authOverlay').style.display='none'}};\nwindow.onBiometricError=function(){document.getElementById('rgAuthMsg').textContent='No se pudo autenticar con biometría. Usa el PIN.'};\nsetTimeout(()=>{try{if(RgaProCamera.biometricAvailable())document.getElementById('rgBio').style.display='block';}catch(e){}const session=localStorage.getItem('rgapro_session');if(!session){document.getElementById('authOverlay').style.display='flex'}else{document.getElementById('authOverlay').style.display='none'}},400);\n</script>'''
    s=s.replace('<body>', '<body>'+insert, 1)

# Ensure the main app can't be shown before authentication.
s=s.replace('<div class="app">','<div class="app" id="mainApp" style="display:none">',1)
s=s.replace('document.getElementById(\'authOverlay\').style.display=\'none\';','document.getElementById(\'authOverlay\').style.display=\'none\';document.getElementById(\'mainApp\').style.display=\'block\';')
s=s.replace('document.getElementById(\'authOverlay\').style.display=\'none\'};','document.getElementById(\'authOverlay\').style.display=\'none\';document.getElementById(\'mainApp\').style.display=\'block\'};')
# Make launcher/in-app logo unambiguously RGA PRO vector (avoid stale RDF assets).
s=s.replace('src="data:image/svg+xml,', 'src="data:image/svg+xml,', 1)
p.write_text(s,encoding='utf-8')

print('robust login overlay patched')
